diagrams/query-builder.text:
// The framework-free half of the query-builder demo, verbatim from
// demos/diagrams/query-builder.html: the four tables, the card tree (a skin over
// the diagram kit's .axk-* classes), the per-column ports, the join pill, join
// adoption and the SQL generator. The React, Vue, Angular and Qwik versions each
// keep an identical copy next to their demo file.
/* eslint-disable @typescript-eslint/no-explicit-any */
import { NodeModel, PortModel } from '@grafloria/element';

export const ACCENT = '#2080e8';
export const CARD_W = 220;
export const HEAD_H = 34;   // header row (8px padding + 13px/700 line)
export const ROW_H = 28;    // 5px padding + 13px line + top border, border-box
const rowCenterY = (i: number) => 1 + HEAD_H + i * ROW_H + ROW_H / 2; // +1 = card top border

export interface Column { name: string; pk?: boolean; fk?: boolean }
export interface Table { id: string; columns: Column[] }

export const cardHeight = (t: Table) => 2 + HEAD_H + t.columns.length * ROW_H; // both borders

export const TABLES: Table[] = [
  { id: 'customers', columns: [
    { name: 'id', pk: true }, { name: 'name' }, { name: 'email' }, { name: 'country' } ] },
  { id: 'orders', columns: [
    { name: 'id', pk: true }, { name: 'customer_id', fk: true }, { name: 'order_date' }, { name: 'total' } ] },
  { id: 'order_items', columns: [
    { name: 'id', pk: true }, { name: 'order_id', fk: true }, { name: 'product_id', fk: true },
    { name: 'quantity' }, { name: 'price' } ] },
  { id: 'products', columns: [
    { name: 'id', pk: true }, { name: 'sku' }, { name: 'name' }, { name: 'unit_price' } ] },
];
export const tableOf = (id: string) => TABLES.find((t) => t.id === id);

/** Column-check state (drives the card DOM AND the SELECT list): table → ticked columns. */
export type Checked = Map<string, Set<string>>;
/** The seed ticks: customers.name, orders.order_date, orders.total. */
export const seedChecked = (): Checked => new Map(TABLES.map((t) => [t.id, new Set(
  t.id === 'customers' ? ['name'] : t.id === 'orders' ? ['order_date', 'total'] : [])]));

// ---- the card, as a SKIN over the kit's .axk-* classes --------------------
// The kit's entityCardContent has no seam for a per-row checkbox (and the html
// layer's allow-list has no form controls), so the TREE is demo-local — but it
// keeps the kit's class contract (.axk-entity/.axk-row/.axk-col) and stamps
// metadata.kitEntity, so bindJoinGuidance and the erTable handles see a
// perfectly ordinary kit card.
export function cardContent(t: Table, cols: Set<string>) {
  const all = cols.size === t.columns.length && t.columns.length > 0;
  const rows = t.columns.map((c) => ({
    tag: 'div',
    className: 'axk-row' + (cols.has(c.name) ? ' qb-on' : ''),
    children: [
      { tag: 'span', className: 'qb-check' + (cols.has(c.name) ? ' on' : ''), attrs: { title: 'include in SELECT' } },
      { tag: 'span', className: 'axk-col', text: c.name },
      ...(c.pk ? [{ tag: 'span', className: 'qb-badge pk', text: 'PK' }]
        : c.fk ? [{ tag: 'span', className: 'qb-badge fk', text: 'FK' }] : []),
    ],
  }));
  return { tag: 'div', className: 'axk-entity qb-card', children: [
    { tag: 'div', className: 'axk-entity-head', children: [
      { tag: 'span', className: 'qb-check qb-head-check qb-all' + (all ? ' on' : ''), attrs: { title: 'select all columns' } },
      { tag: 'span', className: 'qb-title', text: t.id },
    ] },
    { tag: 'div', className: 'axk-entity-body', children: rows },
  ] };
}

// per-column ports on BOTH sides: '<table>.<col>-in' (left target) and
// '<table>.<col>-out' (right source), pinned to the row centres
export const portSpecs = (t: Table) => t.columns.flatMap((c, i) => [
  { id: `${t.id}.${c.name}-in`, side: 'left' as const, type: 'input',
    shape: { shape: 'circle', size: 9 },
    layout: { strategy: 'absolute', args: { units: 'px', x: 0, y: rowCenterY(i) } } },
  { id: `${t.id}.${c.name}-out`, side: 'right' as const, type: 'output',
    shape: { shape: 'circle', size: 9 },
    layout: { strategy: 'absolute', args: { units: 'px', x: CARD_W, y: rowCenterY(i) } } },
]);

export const nodeSpec = (t: Table, position: { x: number; y: number }, cols: Set<string>) => ({
  id: t.id,
  position,
  size: { width: CARD_W, height: cardHeight(t) },
  metadata: {
    html: { content: cardContent(t, cols), interactive: true, padding: 0 },
    kitEntity: { id: t.id, name: t.id, columns: t.columns },
  },
  shape: { type: 'rect', fill: 'none', stroke: 'none' },
  style: { fill: 'transparent', stroke: 'transparent', strokeWidth: 0 },
  ports: portSpecs(t),
});

/** A table dropped from the rail: the same card, built as a live NodeModel. */
export function tableNode(t: Table, position: { x: number; y: number }, cols: Set<string>) {
  const node = new NodeModel({ id: t.id, type: 'rect', position, size: { width: CARD_W, height: cardHeight(t) } } as any);
  node.ports.clear();
  for (const spec of portSpecs(t)) node.addPort(new PortModel({ ...spec, visible: true } as any));
  node.setMetadata('html', { content: cardContent(t, cols), interactive: true, padding: 0 });
  node.setMetadata('kitEntity', { id: t.id, name: t.id, columns: t.columns });
  node.setMetadata('shape', { type: 'rect', fill: 'none', stroke: 'none' });
  node.style = { ...node.style, fill: 'transparent', stroke: 'transparent', strokeWidth: 0 } as any;
  (node as any).setBehavior?.({ resizable: false });
  return node;
}

/** 2px accent, no arrowheads. */
export const JOIN_STYLE = { stroke: ACCENT, strokeWidth: 2, arrowHead: { type: 'none' }, arrowTail: { type: 'none' } };

/** The seed: customers + orders, one INNER join, a few columns ticked. */
export function seedSpec() {
  const checked = seedChecked();
  return {
    nodes: [
      nodeSpec(tableOf('customers')!, { x: 60, y: 80 }, checked.get('customers')!),
      nodeSpec(tableOf('orders')!, { x: 430, y: 250 }, checked.get('orders')!),
    ],
    edges: [{
      id: 'join-1', source: 'customers', target: 'orders',
      sourceHandle: 'customers.id-out', targetHandle: 'orders.customer_id-in',
      type: 'orthogonal',
      style: JOIN_STYLE,
    }],
  };
}

export const JOIN_TYPES = ['INNER', 'LEFT', 'RIGHT', 'FULL'];
export const pillLabel = (type: string) => ({
  id: 'join-type', text: type, position: 0.5, offset: { x: 0, y: 0 },
  style: { fontSize: 10, color: '#fff', background: ACCENT, padding: 6, borderRadius: 999, border: '#fff' },
});
export const parsePort = (pid: string | undefined) => {
  const m = /^([^.]+)\.(.+)-(in|out)$/.exec(pid || '');
  return m ? { table: m[1]!, column: m[2]! } : null;
};
export const joinType = (link: any): string => (link.labels?.[0]?.text ?? 'INNER').toUpperCase();

// ---- join adoption: every link that lands becomes a JOIN ---------------
// (seeded edges AND interactively drawn ones — including a link re-added by
// redo/undo, which re-fires link:added; adoption is idempotent)
export function adoptJoin(link: any): boolean {
  const s = parsePort(link.sourcePortId);
  const t = parsePort(link.targetPortId);
  if (!s || !t) return false;
  if (!link.getMetadata('qbJoin')) link.setMetadata('qbJoin', { source: s, target: t });
  // 2px accent, no arrowheads — set ON the link (the production tool lost
  // this to a CSS specificity fight; the element's own style cannot lose)
  link.updateStyle(JOIN_STYLE);
  if (!link.labels || link.labels.length === 0) link.setLabels([pillLabel('INNER')]);
  return true;
}

/** True when the two tables already share a join (the validator's pair rule). */
export const alreadyJoined = (model: any, a: string, b: string): boolean => model.getLinks().some((l: any) => {
  const j = l.getMetadata('qbJoin');
  return j && ((j.source.table === a && j.target.table === b) || (j.source.table === b && j.target.table === a));
});

/** The join's equation, as the inspector shows it. */
export const joinEquation = (link: any): string => {
  const j = link.getMetadata('qbJoin');
  return `${j.source.table}.${j.source.column} = ${j.target.table}.${j.target.column}`;
};

// ---- the SQL generator (honest: creation-ordered joins, no aliases) ----
export function generateSql(model: any, checked: Checked): string {
  const placed = TABLES.filter((t) => !!model.getNode(t.id));
  if (placed.length === 0) return 'SELECT *';
  const joins = model.getLinks()
    .map((link: any) => ({ link, j: link.getMetadata('qbJoin') }))
    .filter((x: any) => !!x.j);
  const chain = [placed[0]!.id];
  const joinLines: string[] = [];
  for (const { link, j } of joins) {
    const other = chain.includes(j.source.table) ? j.target.table : j.source.table;
    if (!chain.includes(other)) chain.push(other);
    joinLines.push(`${joinType(link)} JOIN ${other} ON ${j.source.table}.${j.source.column} = ${j.target.table}.${j.target.column}`);
  }
  const cols: string[] = [];
  for (const t of placed) {
    if (!chain.includes(t.id)) continue;   // unjoined tables are not in the query
    for (const c of t.columns) if (checked.get(t.id)!.has(c.name)) cols.push(`${t.id}.${c.name}`);
  }
  const select = cols.length
    ? 'SELECT\n' + cols.map((c) => `  ${c}`).join(',\n')
    : 'SELECT *';
  return [`${select}`, `FROM ${chain[0]}`, ...joinLines].join('\n');
}

diagrams/visio-editor.text:
/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * The framework-free half of the Visio-style editor port — every line of it
 * is the JS page's own wiring (demos/diagrams/visio-editor.html), moved here so
 * the four framework versions share ONE copy instead of four drifting ones.
 *
 * The framework file owns the chrome — the toolbar, the zoom cluster and the
 * context menu are rendered by React/Vue/Angular/Qwik from `VisioUi` — and this
 * controller owns the engine: interaction config, page grid + minimap, the
 * stencil rail and shape-data panel, the "Fulfilment" container, the marquee
 * tool, the keyboard chords and the commands behind every button. Each state
 * change is handed back through `onChange(ui)` as a fresh plain object.
 *
 * (Copied verbatim next to the demo in each app — keep the copies identical.)
 */
import {
  registerStencils, bindStencilPalette, bindShapeDataPanel,
  AlignCommand, DistributeCommand, registerTool,
  BringNodeToFrontCommand, SendNodeToBackCommand,
  attachCanvasPlugins, GroupModel, AddGroupCommand, RemoveGroupCommand,
} from '@grafloria/element';

// A SCENARIO, not a shape dump: an order-fulfilment flow you could actually
// hand to someone — the flowchart is the process, the container groups the
// fulfilment steps, and the ER table is the data behind it.
export const VISIO_NODES = [
  { id: 'recv', position: { x: 120, y: 120 }, size: { width: 150, height: 56 }, label: 'Order received' },
  { id: 'chk', position: { x: 340, y: 120 }, size: { width: 150, height: 56 }, label: 'Stock check' },
  { id: 'pick', position: { x: 340, y: 330 }, size: { width: 150, height: 56 }, label: 'Pick items' },
  { id: 'ship', position: { x: 340, y: 430 }, size: { width: 150, height: 56 }, label: 'Ship' },
];
export const VISIO_EDGES = [
  { id: 'e1', source: 'recv', target: 'chk' },
  { id: 'e2', source: 'chk', target: 'pick', label: 'in stock' },
  { id: 'e3', source: 'pick', target: 'ship' },
];

export type BarAction =
  | 'left' | 'right' | 'top' | 'bottom' | 'center-y' | 'center-x'
  | 'dist-h' | 'dist-v' | 'duplicate' | 'group' | 'ungroup' | 'undo' | 'redo';
export type ViewToggle = 'grid' | 'snap' | 'minimap';
export type BarItem =
  | { kind: 'sep' }
  | { kind: 'action'; action: BarAction; label: string; title: string }
  | { kind: 'toggle'; toggle: ViewToggle; label: string; title: string };

/** The toolbar, left to right — the JS page's mk/mkN/mkToggle calls, as data. */
export const BAR: BarItem[] = [
  // T3 — the align/distribute toolbar over the live selection.
  { kind: 'action', action: 'left', label: '⇤ Left', title: 'Align left edges (2+ shapes)' },
  { kind: 'action', action: 'right', label: '⇥ Right', title: 'Align right edges (2+ shapes)' },
  { kind: 'action', action: 'top', label: '⤒ Top', title: 'Align top edges (2+ shapes)' },
  { kind: 'action', action: 'bottom', label: '⤓ Bottom', title: 'Align bottom edges (2+ shapes)' },
  { kind: 'action', action: 'center-y', label: '≡ Middle', title: 'Align horizontal middles (2+ shapes)' },
  { kind: 'action', action: 'center-x', label: '‖ Centre', title: 'Align vertical centres (2+ shapes)' },
  { kind: 'sep' },
  { kind: 'action', action: 'dist-h', label: '↔ Distribute', title: 'Equal horizontal gaps (3+ shapes)' },
  { kind: 'action', action: 'dist-v', label: '↕ Distribute', title: 'Equal vertical gaps (3+ shapes)' },
  { kind: 'sep' },
  { kind: 'action', action: 'duplicate', label: '⧉ Duplicate', title: 'Duplicate the selection (Ctrl/⌘+D)' },
  { kind: 'sep' },
  { kind: 'action', action: 'group', label: '⊞ Group', title: 'Group the selection into a container (Ctrl/⌘+G, 2+ shapes)' },
  { kind: 'action', action: 'ungroup', label: '⊟ Ungroup', title: 'Dissolve the selected shape’s group (Ctrl/⌘+Shift+G)' },
  { kind: 'sep' },
  { kind: 'action', action: 'undo', label: '↶ Undo', title: 'Undo the last edit' },
  { kind: 'action', action: 'redo', label: '↷ Redo', title: 'Redo the undone edit (Ctrl/⌘+Y)' },
  { kind: 'sep' },
  // View toggles — pressed-state buttons driving the LIBRARY's own switches.
  { kind: 'toggle', toggle: 'grid', label: '▦ Grid', title: 'Show the page grid' },
  { kind: 'toggle', toggle: 'snap', label: '⌗ Snap', title: 'Snap dragged shapes and edge points to the 20px grid' },
  { kind: 'toggle', toggle: 'minimap', label: '◱ Minimap', title: 'Show the minimap' },
];

export interface MenuEntry { label: string; enabled: boolean }

/** Everything the chrome paints — plain data, safe for any framework's store. */
export interface VisioUi {
  /** How many nodes are selected (drives every "needs N shapes" button). */
  selected: number;
  canUngroup: boolean;
  canUndo: boolean;
  canRedo: boolean;
  /** The zoom readout, e.g. "100%". */
  zoomPct: string;
  grid: boolean;
  snap: boolean;
  minimap: boolean;
  /** The open context menu, positioned in #vs-canvas-local px, or null. */
  menu: { x: number; y: number; items: MenuEntry[] } | null;
}

export function initialUi(): VisioUi {
  return {
    selected: 0, canUngroup: false, canUndo: false, canRedo: false,
    zoomPct: '100%', grid: true, snap: true, minimap: true, menu: null,
  };
}

/** Each button declares how many shapes it needs; below that it is DISABLED,
 *  not silently inert — an enabled control that does nothing is a bug. */
export function barDisabled(item: BarItem, ui: VisioUi): boolean {
  if (item.kind !== 'action') return false;
  switch (item.action) {
    case 'dist-h': case 'dist-v': return ui.selected < 3;
    case 'duplicate': return ui.selected < 1;
    case 'group': return ui.selected < 2;          // Visio's own minimum
    case 'ungroup': return !ui.canUngroup;
    case 'undo': return !ui.canUndo;
    case 'redo': return !ui.canRedo;
    default: return ui.selected < 2;               // the six aligns
  }
}

const ZOOM_STEP = 1.2;

export interface VisioHosts {
  /** #vs-canvas — wraps the diagram; drop target, menu/zoom positioning box. */
  canvas: HTMLElement;
  /** #vs-rail — the stencil palette paints into it. */
  rail: HTMLElement;
  /** #vs-panel — the shape-data panel paints into it. */
  panel: HTMLElement;
}

export class VisioEditor {
  readonly ui: VisioUi = initialUi();
  readonly diagram: any;
  readonly engine: any;
  /** How many stencil masters the registry took (the JS assert pins 80). */
  registered = 0;
  palette: any = null;
  panel: any = null;
  /** The seeded "Fulfilment" container. */
  box: any = null;

  private plugins: { dispose(): void } | null = null;
  private offs: Array<() => void> = [];
  private menuRuns: Array<() => unknown> = [];
  private disposed = false;

  constructor(
    private readonly api: any,
    private readonly hosts: VisioHosts,
    private readonly onChange: (ui: VisioUi) => void,
  ) {
    this.diagram = api.getModel();
    this.engine = api.getEngine();
  }

  /** The live DiagramInstance (named like the JS page's ctx.instance). */
  get instance(): any { return this.api; }

  async init(): Promise<void> {
    try { await this.setup(); } catch (e) { if (!this.disposed) throw e; }
  }

  private async setup(): Promise<void> {
    const { api, engine, hosts } = this;

    // Every gesture this editor wants — each opt-in at the library level.
    engine.setInteractionConfig({
      enableHelperLines: true,            // T1 + T2: snap guides on drag and resize
      enableGroupMembershipOnDrop: true,  // T8: drop into a container to join it
      enableInPlaceTextEdit: true,        // T10: double-click to rename
      enableGroupDrag: true,
      enableKeyboardNudge: true,          // arrows nudge the selection (Shift = ×10)
      // Draw a connector by dragging from a port and releasing ANYWHERE on the
      // target node; 'alt' keeps a plain body press as MOVE and shift-click as
      // multi-select, while a press on a port glyph always starts a wire.
      enableEasyConnect: true,
      easyConnectModifier: 'alt',
    });

    // GRID — the faint Visio page grid (the Background plugin: an SVG pattern
    // in its own camera-tracked layer). The 20-unit gap equals the snap
    // gridSize: what you see is what you snap to. MINIMAP — the library's live
    // one, slightly smaller than default, nudged above the zoom cluster.
    this.plugins = attachCanvasPlugins(api, {
      background: {
        variant: 'lines', gap: 20, size: 1,
        color: 'rgba(120,130,145,.16)',
        majorEvery: 5, majorColor: 'rgba(120,130,145,.30)',
      },
      minimap: { width: 170, height: 120 },
    } as any);
    const mm = hosts.canvas.querySelector('.grafloria-minimap') as HTMLElement | null;
    if (mm) mm.style.bottom = '76px';   // clear the zoom cluster below it

    // ZOOM — the readout follows the instance's own ViewportController.
    this.offs.push(api.viewport.onChange(() => this.paintPct()));
    this.paintPct();

    // Keyboard chords every canvas product answers (never while typing).
    this.listen('keydown', this.onChord);

    // SNAP-TO-GRID — Visio defaults snap ON, so does this editor.
    this.setSnap(true);

    // T4/T5 — all 8 stencils behind the registry, feeding the palette; T9 —
    // the shape-data panel, driven by each master's dataSchema (or a kit card).
    this.registered = registerStencils(engine.templateRegistry);
    this.palette = bindStencilPalette(api, { palette: hosts.rail, canvas: hosts.canvas }, {
      data: (master: any) => ({ label: master.meta?.name ?? master.id }),
    });
    this.panel = bindShapeDataPanel(api, hosts.panel);

    // A container to drop shapes into (T8). MEMBERSHIP, not just overlap: a
    // frame drawn around two nodes that left them behind on a drag would read
    // as a bug, because the picture says otherwise.
    const box = await engine.addGroup({ name: 'Fulfilment' });
    if (this.disposed) return;
    box.setFrame({ x: 300, y: 290, width: 240, height: 230 });
    await engine.addToGroup(box.id, 'pick');
    await engine.addToGroup(box.id, 'ship');
    if (this.disposed) return;
    this.box = box;

    // MARQUEE — rubber-band select on EMPTY canvas (not inside a container's
    // frame, which drags the container), through the public registerTool seam.
    this.offs.push(registerTool(this.marqueeTool()) as unknown as () => void);

    // CONTEXT MENU — click-away and Escape dismiss it, like every real menu.
    // (A press in the zoom cluster leaves it open: on the JS page that cluster
    // stops pointerdown from propagating, so the dismiss listener never sees it.)
    this.listen('pointerdown', (e: Event) => {
      const t = e.target as Element | null;
      if (!t?.closest?.('#vs-menu, #vs-zoom')) this.closeMenu();
    });
    this.listen('keydown', (e: Event) => { if ((e as KeyboardEvent).key === 'Escape') this.closeMenu(); });

    this.offs.push(api.on('selection:change', () => this.syncBar()));
    this.syncBar();
    api.renderNow();

    // The port's gesture script reads the model through this — the JS page's
    // gate reads the same objects through the shell's window.__demoCtx.
    (globalThis as any).__visioEditor = this;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const off of this.offs.splice(0)) { try { off(); } catch { /* instance already gone */ } }
    this.palette?.destroy();
    this.panel?.destroy();
    this.plugins?.dispose();
    if ((globalThis as any).__visioEditor === this) delete (globalThis as any).__visioEditor;
  }

  // ── zoom cluster: −  %  +  fit (each one call into the ViewportController) ──
  zoomIn(): void { this.api.viewport.setZoom(this.api.viewport.getZoom() * ZOOM_STEP); this.api.renderNow(); }
  zoomOut(): void { this.api.viewport.setZoom(this.api.viewport.getZoom() / ZOOM_STEP); this.api.renderNow(); }
  zoomReset(): void { this.api.viewport.setZoom(1); this.api.renderNow(); }
  fit(): void { this.api.fitView(); this.api.renderNow(); }

  // ── the toolbar ──────────────────────────────────────────────────────────
  /** A bar button. Like the JS page's mk(): an action runs while something is
   *  selected — except Undo and Redo, which act with nothing selected too. */
  async run(action: BarAction): Promise<void> {
    const ids = this.selectedIds();
    const cm = this.engine.commandManager;
    const later = () => setTimeout(() => this.syncBar(), 0);
    if (!ids.length && action !== 'undo' && action !== 'redo') return;
    switch (action) {
      case 'left': case 'right': case 'top': case 'bottom': case 'center-y': case 'center-x':
        await cm.execute(new AlignCommand(ids, action)); break;
      case 'dist-h': await cm.execute(new DistributeCommand(ids, 'horizontal')); break;
      case 'dist-v': await cm.execute(new DistributeCommand(ids, 'vertical')); break;
      case 'duplicate': await this.engine.duplicate(); break;
      case 'group': await this.groupSelection(); return;
      case 'ungroup': await this.ungroupSelection(); return;
      case 'undo': later(); await cm.undo(); break;
      case 'redo': later(); await cm.redo(); break;
    }
    later();
  }

  /** A view toggle — each drives the LIBRARY's own switch, not a local flag:
   *  Grid flips DiagramStore.gridEnabled (the Background plugin watches it),
   *  Snap the engine's snap-to-grid config, Minimap DiagramStore.showMinimap. */
  toggle(which: ViewToggle): void {
    const on = !this.ui[which];
    this.ui[which] = on;
    if (which === 'grid') this.engine.getStore().set('gridEnabled', on);
    else if (which === 'snap') this.setSnap(on);
    else this.engine.getStore().set('showMinimap', on);
    this.api.renderNow();
    this.emit();
  }

  /** setInteractionConfig merges SHALLOWLY, so patch the nested objects whole.
   *  Alignment guides still win over the grid per axis (computeSnap). */
  setSnap(on: boolean): void {
    const cfg = this.engine.getInteractionConfig();
    this.engine.setInteractionConfig({
      waypointEditor: { ...cfg.waypointEditor, snapToGrid: on },
      controlPointEditor: { ...cfg.controlPointEditor, snapToGrid: on },
    });
  }

  // ── group / ungroup — real containers, ONE undo step each ────────────────
  // The GroupModel is populated (members + fitted frame) BEFORE it enters the
  // diagram, so a single AddGroupCommand carries the whole creation; ungroup's
  // RemoveGroupCommand snapshots the group, so one Ctrl+Z resurrects it whole.
  async groupSelection(): Promise<any> {
    const ids = this.selectedIds();
    if (ids.length < 2) return null;
    const g = new GroupModel({ name: 'Group' } as any);
    for (const id of ids) g.addMember(id);
    g.fitToContents(this.diagram);
    await this.engine.commandManager.execute(new AddGroupCommand(g));
    this.api.renderNow();
    this.syncBar();
    return this.diagram.getGroup(g.id);
  }

  async ungroupSelection(): Promise<string | null> {
    const g = this.groupInScope();
    if (!g) return null;
    await this.engine.commandManager.execute(new RemoveGroupCommand(g.id));
    this.api.renderNow();
    this.syncBar();
    return g.id;
  }

  // ── context menu: node / edge / canvas, every entry an existing command ──
  openMenuAt(clientX: number, clientY: number): void {
    const { api, diagram, engine } = this;
    const rect = this.hosts.canvas.getBoundingClientRect();
    const w = api.viewport.clientToWorld(clientX, clientY, rect);
    const node = diagram.getNodeAtPosition(w.x, w.y);
    const link = node ? null : api.interaction.getLinkAtPosition(w.x, w.y, engine);
    let entries: Array<{ label: string; run: () => unknown; enabled?: boolean }>;
    if (node) {
      // Right-click selects what it targets, so Duplicate/Delete act on the
      // node the user sees lit.
      if (!node.isSelected?.()) { diagram.selectNode(node); api.renderNow(); this.syncBar(); }
      entries = [
        { label: 'Rename', run: () => api.beginLabelEdit({ type: 'node', nodeId: node.id }) },
        { label: 'Duplicate', run: () => engine.duplicate() },
        { label: 'Delete', run: () => engine.removeNode(node.id) },
        { label: 'Bring to front', run: () => engine.commandManager.execute(new BringNodeToFrontCommand(node.id)) },
        { label: 'Send to back', run: () => engine.commandManager.execute(new SendNodeToBackCommand(node.id)) },
      ];
    } else if (link) {
      entries = [
        // Rename edits an EXISTING label (a labels[] entry or the display
        // label); a truly unlabeled edge shows the entry disabled.
        { label: 'Rename label', run: () => api.beginLabelEdit({ type: 'link-label', linkId: link.id, labelIndex: 0 }),
          enabled: (link.labels?.length ?? 0) > 0 || !!link.getLabel?.() },
        { label: 'Delete', run: () => engine.removeLink(link.id) },
      ];
    } else {
      entries = [
        { label: 'Select all', run: () => { diagram.selectAll(); } },
        { label: 'Paste', run: () => engine.paste(), enabled: engine.hasClipboardData?.() === true },
      ];
    }
    this.menuRuns = entries.map((e) => e.run);
    this.ui.menu = {
      x: clientX - rect.left,
      y: clientY - rect.top,
      items: entries.map((e) => ({ label: e.label, enabled: e.enabled !== false })),
    };
    this.emit();
  }

  async runMenuItem(index: number): Promise<void> {
    const run = this.menuRuns[index];
    this.closeMenu();
    if (!run) return;
    await run();
    this.api.renderNow();
    this.syncBar();
  }

  closeMenu(): void {
    if (!this.ui.menu) return;
    this.ui.menu = null;
    this.emit();
  }

  // ── state ────────────────────────────────────────────────────────────────
  syncBar(): void {
    const cm = this.engine.commandManager;
    this.ui.selected = this.selectedIds().length;
    this.ui.canUngroup = !!this.groupInScope();
    this.ui.canUndo = !!cm.canUndo?.();
    this.ui.canRedo = !!cm.canRedo?.();
    this.emit();
  }

  private paintPct(): void {
    this.ui.zoomPct = `${Math.round(this.api.viewport.getZoom() * 100)}%`;
    this.emit();
  }

  private emit(): void {
    if (this.disposed) return;
    const { menu } = this.ui;
    this.onChange({ ...this.ui, menu: menu ? { ...menu, items: menu.items.map((m) => ({ ...m })) } : null });
  }

  private selectedIds(): string[] {
    return this.diagram.getSelectedNodes().map((n: any) => n.id);
  }

  private groupInScope(): any {
    const sel = this.selectedIds();
    if (!sel.length) return null;
    return this.diagram.getGroups().find((g: any) => sel.some((id) => g.members.has(id))) ?? null;
  }

  private listen(type: string, handler: (e: Event) => void): void {
    document.addEventListener(type, handler);
    this.offs.push(() => document.removeEventListener(type, handler));
  }

  /** Ctrl/⌘+= in, Ctrl/⌘+− out, Ctrl/⌘+0 → 100%, Ctrl/⌘+Shift+F → fit,
   *  Ctrl/⌘+G group, +Shift ungroup. preventDefault keeps the BROWSER's
   *  zoom/find out of it. Never while typing in a field. */
  private onChord = (ev: Event): void => {
    const e = ev as KeyboardEvent;
    if (!(e.ctrlKey || e.metaKey)) return;
    const t = e.target as HTMLElement | null;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    if (e.key === '=' || e.key === '+') { e.preventDefault(); this.zoomIn(); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); this.zoomOut(); }
    else if (e.key === '0') { e.preventDefault(); this.zoomReset(); }
    else if (e.shiftKey && (e.key === 'f' || e.key === 'F')) { e.preventDefault(); this.fit(); }
    else if (e.key === 'g' || e.key === 'G') {
      e.preventDefault();
      if (e.shiftKey) void this.ungroupSelection();
      else void this.groupSelection();
    }
  };

  /** The rubber band: Shift or Ctrl/⌘ adds; Escape (routed to onCancel by the
   *  binder) removes the band AND rolls the selection back to before the press. */
  private marqueeTool(): any {
    const { api, diagram } = this;
    const host: HTMLElement = api.container;   // the diagram's own box (= #vs-canvas's)
    let overlay: HTMLDivElement | null = null;
    let start: { world: { x: number; y: number }; screen: { x: number; y: number } } | null = null;
    let baseSelection = new Set<string>();
    const showBox = (a: { x: number; y: number }, b: { x: number; y: number }) => {
      if (!overlay) {
        overlay = document.createElement('div');
        overlay.className = 'vs-marquee';
        overlay.style.cssText =
          'position:absolute;pointer-events:none;z-index:20;border:1px dashed #3B52D9;' +
          'background:rgba(59,82,217,.12);border-radius:2px;';
        host.appendChild(overlay);
      }
      overlay.style.left = Math.min(a.x, b.x) + 'px';
      overlay.style.top = Math.min(a.y, b.y) + 'px';
      overlay.style.width = Math.abs(b.x - a.x) + 'px';
      overlay.style.height = Math.abs(b.y - a.y) + 'px';
    };
    const clearBox = () => { overlay?.remove(); overlay = null; };
    const worldBounds = (n: any) => {
      const p = typeof n.getWorldPosition === 'function' ? n.getWorldPosition() : n.position;
      return { x: p.x, y: p.y, w: n.size.width, h: n.size.height };
    };
    const additiveOf = (ev: any) => ev.modifiers.shift || ev.modifiers.ctrl || ev.modifiers.meta;
    const applySelection = (rect: { ax: number; ay: number; bx: number; by: number }, additive: boolean) => {
      const x1 = Math.min(rect.ax, rect.bx), y1 = Math.min(rect.ay, rect.by);
      const x2 = Math.max(rect.ax, rect.bx), y2 = Math.max(rect.ay, rect.by);
      for (const n of diagram.getNodes()) {
        const b = worldBounds(n);
        const inside = b.x >= x1 && b.y >= y1 && b.x + b.w <= x2 && b.y + b.h <= y2;
        n.setSelected(inside || (additive && baseSelection.has(n.id)));
      }
      api.renderNow();
      this.syncBar();
    };
    const overGroupFrame = (w: { x: number; y: number }) => diagram.getGroups().some((g: any) => {
      const r = g.getOuterBounds?.();
      return r && w.x >= r.x && w.x <= r.x + r.width && w.y >= r.y && w.y <= r.y + r.height;
    });
    return {
      id: 'vs-marquee',
      priority: 1,
      hitTest: (ev: any, hit: any) => !!hit.empty && !overGroupFrame(ev.world),
      onPointerDown: (ev: any) => {
        start = { world: { ...ev.world }, screen: { ...ev.screen } };
        baseSelection = new Set(diagram.getSelectedNodes().map((n: any) => n.id));
        if (!additiveOf(ev)) { diagram.clearSelection(); baseSelection.clear(); }
      },
      onPointerMove: (ev: any) => {
        if (!start) return;
        showBox(start.screen, ev.screen);
        applySelection({ ax: start.world.x, ay: start.world.y, bx: ev.world.x, by: ev.world.y }, additiveOf(ev));
      },
      onPointerUp: (ev: any) => {
        if (start) applySelection({ ax: start.world.x, ay: start.world.y, bx: ev.world.x, by: ev.world.y }, additiveOf(ev));
        start = null;
        clearBox();
      },
      onCancel: () => {
        if (start) {
          for (const n of diagram.getNodes()) n.setSelected(baseSelection.has(n.id));
          api.renderNow();
          this.syncBar();
        }
        start = null;
        clearBox();
      },
    };
  }
}

interaction/chatbot-flow.text:
// The chatbot builder's behaviour — translated line for line from the setup()
// of demos/interaction/chatbot-flow.html. It owns the engine side (repainting a
// card, re-seating its ports, connecting, new steps, the Preview's walk along
// the links); the framework component owns the markup, reads this controller's
// public fields, and re-renders when it calls bump(). Framework-free: the same
// file sits next to the chatbot-flow demo in the React, Vue, Angular and Qwik apps.
import { LinkModel, NodeModel } from '@grafloria/engine';
import {
  FLOW0, URL_BOOK, portKind, lineStyle, cardContent, stripPorts, measure, portList, portModel,
  nodeSpec, edgeSpecs, disposeMeasure, type Step, type Block, type Btn,
} from './chatbot-flow-data';

/** One row of the Preview chat: a bubble, a system line, a row of buttons, the typing dots. */
export interface ChatItem {
  id: number;
  kind: 'msg' | 'sys' | 'btns' | 'typing';
  cls?: string;              // msg: pv-bot / pv-user / pv-img
  text?: string;
  act?: boolean;             // sys: an action ran
  buttons?: Array<{ label: string; chosen: boolean }>;
}
interface Waiting { stepId: string; field: string; ar: boolean }
interface MenuCtx { world: { x: number; y: number }; from: string | null }

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
const isArabic = (s: string) => /[؀-ۿ]/.test(s);
const uid = () => Math.random().toString(36).slice(2, 7);
const VALID: Record<string, RegExp> = { Phone: /^\+?[\d\s()-]{7,}$/, Email: /^\S+@\S+\.\S+$/, Text: /\S/ };

export class ChatbotFlowController {
  // ---- what the template reads ---------------------------------------------
  steps = new Map<string, Step>();
  selected: string | null = null;     // selected step id
  savedText = '✓ Saved';
  dirty = false;
  publishDisabled = true;
  menuOpen = false;
  menuLeft = 0;
  menuTop = 0;
  previewOn = false;
  chat: ChatItem[] = [];
  waiting: Waiting | null = null;
  pvText = '';
  /** The Preview's delays are multiplied by this (0 = instant). */
  pvSpeed = 1;

  /** Re-render the component; set by the framework. */
  bump: () => void = () => {};

  get step(): Step | null { return (this.selected && this.steps.get(this.selected)) || null; }
  get kindLabel(): string {
    const k = this.step?.kind;
    return k === 'trigger' ? 'Trigger' : k === 'actions' ? 'Actions' : 'Send Message';
  }
  get stepCount(): number { return this.steps.size; }
  get linkCount(): number { return this.model ? this.model.getLinks().length : 0; }
  /** "Choose Next Step" shows unless this is a trigger that already leads somewhere. */
  get showNext(): boolean { const s = this.step; return !!s && (s.kind !== 'trigger' || !this.outLink(s.id + '__then')); }
  get waitText(): string { return this.waiting ? `Waiting for your ${this.waiting.field.toLowerCase()}…` : 'Waiting for your reply…'; }
  get inputPlaceholder(): string {
    return this.waiting ? (this.waiting.field === 'Phone' ? '+20 100 123 4567' : 'Type your reply…') : 'Type a message…';
  }
  /** The delay's seconds box shows what was typed; the card shows the clamped value. */
  secsValue(b: Block): string { return this.secsTyped.get(b) ?? String(b.secs); }

  // ---- engine side -----------------------------------------------------------
  private api: any = null;
  private model: any = null;
  private engine: any = null;
  private root!: HTMLElement;     // the stage: #side + #canvas
  private host!: HTMLElement;     // #canvas — the flow and its chrome
  private offs: Array<() => void> = [];
  private seq = 8;                // "Send Message #n" for new steps
  private running: string | null = null;   // the step the Preview is on
  private runningLink: any = null;
  private removed = new Map<string, Step>();
  private menuCtx: MenuCtx | null = null;
  private lastUp: { x: number; y: number } | null = null;
  private panAnim = 0;
  private secsTyped = new WeakMap<Block, string>();
  private P = { token: 0 };
  private chatSeq = 0;
  private btnRows = new Map<number, { stepId: string; buttons: Btn[] }>();

  /** Mount on a fresh instance: `root` holds #side and #canvas. Safe to call again. */
  init(instance: any, root: HTMLElement): void {
    this.teardown();
    this.api = instance;
    this.model = instance.getModel();
    this.engine = instance.getEngine();
    this.root = root;
    this.host = root.querySelector('#canvas') as HTMLElement;
    this.selected = null; this.running = null; this.runningLink = null; this.seq = 8;
    this.savedText = '✓ Saved'; this.dirty = false; this.publishDisabled = true;
    this.menuOpen = false; this.menuCtx = null;
    this.previewOn = false; this.chat = []; this.waiting = null; this.pvText = '';
    this.removed.clear();
    this.btnRows.clear();

    // The cards are measured in the page's CSS, so the flow goes in once the
    // component (and its stylesheet) is on the page.
    const flow = FLOW0();
    this.steps = new Map(flow.steps.map((s) => [s.id, s]));
    instance.setNodes(flow.steps.map((s) => nodeSpec(s)));
    instance.setEdges(edgeSpecs(flow.links));
    const model = this.model;
    // ManyChat keeps a card's words at every zoom: widen every level-of-detail
    // tier to draw everything (a bot is tens of steps, not thousands).
    try {
      const cfg = model.getLODConfig();
      const all = new Set<unknown>();
      for (const t of cfg.tiers) for (const f of t.features) all.add(f);
      for (const t of cfg.tiers) for (const f of all) t.features.add(f);
      model.setLODConfig(cfg);
    } catch { /* an engine without LOD config draws everything anyway */ }
    for (const n of model.getNodes()) n.behavior.resizable = false;

    // The chrome over the canvas keeps its pointer, wheel and double-click.
    const stop = (e: Event) => e.stopPropagation();
    for (const el of Array.from(this.host.querySelectorAll('.cv-top, #cv-fab, .cv-zoom, #mc-menu, #pv'))) {
      for (const t of ['pointerdown', 'wheel', 'dblclick']) {
        el.addEventListener(t, stop);
        this.offs.push(() => el.removeEventListener(t, stop));
      }
    }

    // ---- selection drives the editor -----------------------------------------
    this.offs.push(instance.on('selection:change', ({ nodes }: any) => this.select(nodes.length === 1 ? nodes[0].id : null)));
    // A deleted step keeps its data aside, so an undo brings back a card the
    // editor and the Preview still understand.
    this.offs.push(model.on('node:removed', (n: any) => {
      if (!n || !this.steps.has(n.id)) return;
      this.removed.set(n.id, this.steps.get(n.id)!);
      this.steps.delete(n.id);
      if (this.selected === n.id) this.select(null);
      this.bump();
    }));
    this.offs.push(model.on('node:added', (n: any) => {
      if (n && this.removed.has(n.id)) { this.steps.set(n.id, this.removed.get(n.id)!); this.removed.delete(n.id); this.bump(); }
    }));
    this.offs.push(model.on('link:added', () => { if (!this.selected) this.bump(); }));
    this.offs.push(model.on('link:removed', () => { if (!this.selected) this.bump(); }));

    // ---- the line a button draws: one next step per output --------------------
    this.offs.push(instance.on('connect', ({ link }: any) => setTimeout(() => {
      for (const l of model.getLinks()) if (l !== link && l.sourcePortId === link.sourcePortId) model.removeLink(l.id);
      link.pathType = 'bezier';
      link.updateStyle(lineStyle(link.sourcePortId));
      this.api.renderNow(); this.markDirty();
    }, 0)));

    // Where a dragged line is let go decides what it means. The engine connects
    // a drop ON (or near) an input dot by itself; the page adds ManyChat's two
    // other answers: over a card's BODY, connect to that card; over empty
    // canvas, offer to create the next step right there.
    const onUp = (e: PointerEvent) => { this.lastUp = { x: e.clientX, y: e.clientY }; };
    window.addEventListener('pointerup', onUp, true);
    this.offs.push(() => window.removeEventListener('pointerup', onUp, true));
    this.offs.push(this.engine.eventBus.on('connection:cancel', (p: any) => setTimeout(() => {
      const src = p?.sourcePort?.id, lastUp = this.lastUp;
      if (!src || !lastUp || portKind(src) === 'in') return;
      const r = this.host.getBoundingClientRect();
      const w = this.api.viewport.clientToWorld(lastUp.x, lastUp.y, r);
      const over = model.getNodes().filter((n: any) => w.x >= n.position.x && w.x <= n.position.x + n.size.width
        && w.y >= n.position.y && w.y <= n.position.y + n.size.height).pop();
      if (!over) { this.openMenu(lastUp.x, lastUp.y, { world: w, from: src }); return; }
      const fromNode = model.getNodeByPortId(src);
      if (over === fromNode || !over.getPort(over.id + '__in')) return;
      this.connect(src, over.id);
      this.api.renderNow(); this.markDirty();
    }, 0)));

    // The next-step menu closes on any press outside it, and on Escape.
    const onDown = (e: PointerEvent) => {
      const menu = this.host.querySelector('#mc-menu');
      if (this.menuOpen && menu && !menu.contains(e.target as Node)) this.closeMenu();
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') this.closeMenu(); };
    document.addEventListener('pointerdown', onDown, true);
    document.addEventListener('keydown', onKey);
    this.offs.push(() => document.removeEventListener('pointerdown', onDown, true));
    this.offs.push(() => document.removeEventListener('keydown', onKey));

    this.frame();
    this.bump();
  }

  /** Unmount: listeners off, the Preview stopped, the measuring twin removed. */
  destroy(): void {
    this.teardown();
    disposeMeasure();
  }

  private teardown(): void {
    for (const off of this.offs.splice(0)) { try { off(); } catch { /* already gone */ } }
    this.P.token++;
    this.panAnim++;
  }

  // ---- repaint: content, size and ports follow the step's data ------------
  private paint(id: string | null): void {
    const step = id ? this.steps.get(id) : undefined, node = id ? this.model.getNode(id) : undefined;
    if (!step || !node) return;
    const m = measure(step);
    node.setMetadata('html', { content: stripPorts(cardContent(step, { sel: id === this.selected, run: id === this.running })), padding: 0 });
    if (node.size.width !== m.w || node.size.height !== m.h) node.setSize(m.w, m.h);
    const want = portList(step, m), keep = new Set(want.map((p) => p.id));
    for (const port of node.getPorts()) {
      if (keep.has(port.id)) continue;
      for (const l of this.model.getLinks()) if (l.sourcePortId === port.id || l.targetPortId === port.id) this.model.removeLink(l.id);
      node.removePort(port.id);
    }
    for (const p of want) {
      const have = node.getPort(p.id);
      if (!have) { node.addPort(portModel(p)); continue; }
      const a = have.layout && have.layout.args;
      if (!a || a.x !== p.x || a.y !== p.y) {
        // Re-seat a moved port under the SAME id, so its lines stay attached.
        node.removePort(p.id);
        node.addPort(portModel(p));
      }
    }
  }

  private outLink(pid: string): any { return this.model?.getLinks().find((l: any) => l.sourcePortId === pid) || null; }
  private stepOf(l: any): string | undefined { return this.model.getNodeByPortId(l.targetPortId)?.id; }
  private connect(srcPid: string, tgtId: string): any {
    for (const l of this.model.getLinks()) if (l.sourcePortId === srcPid) this.model.removeLink(l.id);
    const l: any = new LinkModel(srcPid, tgtId + '__in', 'bezier' as never);
    l.sourceNodeId = this.model.getNodeByPortId(srcPid)?.id;
    l.targetNodeId = tgtId;
    l.updateStyle(lineStyle(srcPid));
    this.model.addLink(l);
    return l;
  }

  // ---- the top bar, zoom and frame ------------------------------------------
  private markDirty(): void {
    this.savedText = '● Unsaved changes'; this.dirty = true; this.publishDisabled = false;
    this.bump();
  }
  publish(): void {
    this.savedText = '✓ Published'; this.dirty = false; this.publishDisabled = true;
    this.bump();
  }
  private frame(): void { this.api.fitView(60); this.api.renderNow(); }
  zoomIn(): void { this.api.viewport.setZoom(this.api.viewport.getZoom() * 1.2); this.api.renderNow(); }
  zoomOut(): void { this.api.viewport.setZoom(this.api.viewport.getZoom() / 1.2); this.api.renderNow(); }
  async tidy(): Promise<void> {
    await this.engine.layout('dagre', { direction: 'LR', nodeSpacing: 36, rankSpacing: 90 });
    this.frame(); this.markDirty();
  }

  // ---- selection drives the editor -----------------------------------------
  private select(id: string | null): void {
    const prev = this.selected;
    this.selected = id && this.steps.has(id) ? id : null;
    if (prev && prev !== this.selected) this.paint(prev);
    if (this.selected) this.paint(this.selected);
    this.api.renderNow();
    this.secsTyped = new WeakMap();
    this.bump();
  }
  /** Select a step on the canvas (the selection event then opens it on the left). */
  selectStep(id: string | null): void {
    this.model.clearSelection?.();
    const n = id ? this.model.getNode(id) : null;
    if (n) this.model.selectNode(n); else this.select(null);
    this.api.renderNow();
  }

  // ---- new steps -------------------------------------------------------------
  private newStep(kind: string, x: number, y: number): Step {
    const id = 's' + Date.now().toString(36) + Math.floor(Math.random() * 1e4);
    const step: Step = kind === 'actions'
      ? { id, kind, title: 'Actions', x, y, actions: [{ id: 'a1', label: 'Notify assignees', sub: '1 person via e-mail' }] }
      : { id, kind: 'message', title: `Send Message #${this.seq++}`, x, y, blocks: [{ id: 't', kind: 'text', text: '', buttons: [] }] };
    this.steps.set(id, step);
    const spec = nodeSpec(step);
    const node: any = new NodeModel({ id, type: 'rect', position: { x, y }, size: spec.size } as never);
    node.ports.clear();
    for (const p of portList(step, measure(step))) node.addPort(portModel(p));
    for (const [k, v] of Object.entries(spec.metadata)) node.setMetadata(k, v);
    node.setMetadata('shape', spec.shape);
    node.behavior.resizable = false;
    node.style = { ...node.style, ...spec.style };
    this.model.addNode(node);
    this.markDirty();
    return step;
  }

  // ---- "Choose next step": from the sidebar, the + button, or a line let go on empty canvas
  private openMenu(clientX: number, clientY: number, mctx: MenuCtx): void {
    const r = this.host.getBoundingClientRect();
    this.menuCtx = mctx;
    this.menuLeft = Math.min(Math.max(8, clientX - r.left), r.width - 240);
    this.menuTop = Math.min(Math.max(54, clientY - r.top), r.height - 140);
    this.menuOpen = true;
    this.bump();
    const menu = () => this.host.querySelector<HTMLElement>('#mc-menu');
    this.whenRendered(() => !!menu() && !menu()!.hidden, () => menu()!.querySelector('button')?.focus({ preventScroll: true }));
  }
  closeMenu(): void {
    if (!this.menuOpen && !this.menuCtx) return;
    this.menuOpen = false; this.menuCtx = null;
    this.bump();
  }
  pickMenu(kind: 'message' | 'actions'): void {
    if (!this.menuCtx) return;
    const { world, from } = this.menuCtx;
    this.closeMenu();
    const step = this.newStep(kind, Math.round(world.x), Math.round(world.y - 24));
    if (from) this.connect(from, step.id);
    this.api.renderNow();
    this.selectStep(step.id);
  }
  private viewCentre() {
    const r = this.host.getBoundingClientRect();
    return this.api.viewport.clientToWorld(r.left + r.width / 2 - 110, r.top + r.height / 2 - 60, r);
  }
  /** The blue + : a new step in the middle of the view. */
  fab(r: DOMRect): void { this.openMenu(r.left - 236, r.bottom + 8, { world: this.viewCentre(), from: null }); }

  // ---- the step editor -------------------------------------------------------
  private blockOf(step: Step, id?: string): Block | undefined { return step.blocks?.find((b) => b.id === id); }
  private changed(rerenderSide: boolean): void {
    this.paint(this.selected); this.api.renderNow(); this.markDirty();
    if (rerenderSide) this.secsTyped = new WeakMap();
    this.bump();
  }
  /** A keystroke in the editor: `field` as the page names it (title, text, btn, collect, secs, caption, a-label, a-sub). */
  edit(field: string, value: string, blockId?: string, itemId?: string): void {
    const step = this.step;
    if (!step) return;
    const b = this.blockOf(step, blockId);
    if (field === 'title') step.title = value;
    else if (field === 'text' && b) b.text = value;
    else if (field === 'btn' && b) { const x = b.buttons!.find((y) => y.id === itemId); if (x) x.title = value; }
    else if (field === 'collect' && b) b.field = value;
    else if (field === 'secs' && b) { b.secs = Math.max(1, Math.min(20, Number(value) || 1)); this.secsTyped.set(b, value); }
    else if (field === 'caption' && b) b.caption = value;
    else if (field === 'a-label' || field === 'a-sub') {
      const a = step.actions?.find((x) => x.id === itemId);
      if (a) a[field === 'a-label' ? 'label' : 'sub'] = value;
    }
    this.changed(false);
  }
  addButton(blockId: string): void {
    const b = this.step && this.blockOf(this.step, blockId);
    if (!b) return;
    b.buttons!.push({ id: uid(), title: 'Button ' + (b.buttons!.length + 1) });
    this.changed(true);
    const inputs = () => this.root.querySelectorAll<HTMLInputElement>(`#side input[data-block="${b.id}"][data-field="btn"]`);
    this.whenRendered(() => inputs().length === b.buttons!.length, () => { const all = inputs(); all[all.length - 1].select(); });
  }
  removeButton(blockId: string, btnId: string): void {
    const b = this.step && this.blockOf(this.step, blockId);
    if (!b) return;
    b.buttons = b.buttons!.filter((x) => x.id !== btnId);
    this.changed(true);
  }
  toggleUrl(blockId: string, btnId: string): void {
    const x = this.step && this.blockOf(this.step, blockId)?.buttons?.find((y) => y.id === btnId);
    if (!x) return;
    x.url = x.url ? undefined : URL_BOOK;
    this.changed(true);
  }
  removeBlock(blockId: string): void {
    const step = this.step;
    if (!step?.blocks) return;
    step.blocks = step.blocks.filter((x) => x.id !== blockId);
    this.changed(true);
  }
  addBlock(k: 'text' | 'image' | 'delay' | 'collect'): void {
    const step = this.step;
    if (!step?.blocks) return;
    if (k === 'collect' && step.blocks.some((x) => x.kind === 'collect')) return;
    step.blocks.push(k === 'text' ? { id: uid(), kind: 'text', text: '', buttons: [] } : k === 'image' ? { id: uid(), kind: 'image', caption: 'Our office' }
      : k === 'delay' ? { id: uid(), kind: 'delay', secs: 2 } : { id: uid(), kind: 'collect', field: 'Email' });
    this.changed(true);
  }
  addAction(): void { const s = this.step; if (!s?.actions) return; s.actions.push({ id: uid(), label: 'Add tag', sub: 'New lead' }); this.changed(true); }
  removeAction(id: string): void { const s = this.step; if (!s?.actions) return; s.actions = s.actions.filter((x) => x.id !== id); this.changed(true); }
  addTrigger(): void { const s = this.step; if (!s?.triggers) return; s.triggers.push({ label: 'User comments on a post', sub: 'Any post' }); this.changed(true); }
  /** "Choose Next Step": the menu opens beside the button, the new step lands right of the card. */
  chooseNext(r: DOMRect): void {
    const step = this.step;
    if (!step) return;
    const node = this.model.getNode(step.id), from = step.kind === 'trigger' ? step.id + '__then' : step.id + '__next';
    this.openMenu(r.right + 12, r.top - 40, { world: { x: node.position.x + node.size.width + 90, y: node.position.y + 24 }, from });
  }
  /** Through the engine's command stack, so ⌘Z / Ctrl+Z brings the step back. */
  deleteStep(): void {
    const step = this.step;
    if (!step) return;
    this.engine.removeNode(step.id).then(() => { this.api.renderNow(); this.markDirty(); });
  }

  // ---- Preview: the bot, run along the links ---------------------------------
  private push(item: Omit<ChatItem, 'id'>): ChatItem {
    const it = { id: ++this.chatSeq, ...item };
    this.chat = [...this.chat, it];
    this.bump();
    this.scrollSoon();
    return it;
  }
  private scroll(): void {
    const chat = this.host?.querySelector('#pv-chat');
    if (chat) chat.scrollTop = chat.scrollHeight;
  }
  private bubble(cls: string, text: string): void { this.push({ kind: 'msg', cls, text }); }
  private sys(text: string, act = false): void { this.push({ kind: 'sys', text, act }); }
  // Pan (briefly animated) until a card sits inside the free part of the canvas.
  private reveal(id: string): void {
    const node = this.model.getNode(id);
    if (!node) return;
    const r = this.host.getBoundingClientRect(), vp = this.api.viewport, z = vp.getZoom();
    const a = vp.worldToClient(node.position.x, node.position.y, r);
    const b = vp.worldToClient(node.position.x + node.size.width, node.position.y + node.size.height, r);
    const free = { left: r.left + 24, right: r.right - (this.previewOn ? 372 : 24), top: r.top + 64, bottom: r.bottom - 24 };
    if (a.x >= free.left && b.x <= free.right && a.y >= free.top && b.y <= free.bottom) return;
    const tx = (free.left + free.right) / 2, ty = Math.min((free.top + free.bottom) / 2, free.top + (b.y - a.y) / 2);
    const dx = ((a.x + b.x) / 2 - tx) / z, dy = ((a.y + b.y) / 2 - ty) / z;
    const from = vp.getViewport(), t0 = performance.now(), dur = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 320;
    const job = ++this.panAnim;
    const step = (now: number) => {
      if (job !== this.panAnim) return;
      const k = dur ? Math.min(1, (now - t0) / dur) : 1, e = 1 - Math.pow(1 - k, 3);
      vp.setViewport({ ...from, x: from.x + dx * e, y: from.y + dy * e });
      this.api.renderNow();
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }
  private setRunning(id: string | null, link?: any): void {
    const prev = this.running;
    this.running = id;
    if (prev) this.paint(prev);
    if (id) { this.paint(id); this.reveal(id); }
    if (this.runningLink && this.model.getLink?.(this.runningLink.id) !== undefined) this.runningLink.updateStyle(lineStyle(this.runningLink.sourcePortId));
    this.runningLink = link || null;
    if (this.runningLink) this.runningLink.updateStyle(lineStyle(this.runningLink.sourcePortId, true));
    this.api.renderNow();
  }
  private setWaiting(w: Waiting | null): void {
    this.waiting = w;
    this.bump();
    this.scrollSoon();   // the wait bar changes the chat's height
    const box = () => this.host.querySelector<HTMLInputElement>('#pv-input');
    if (w) this.whenRendered(() => !!box() && !box()!.disabled, () => box()!.focus({ preventScroll: true }));
  }
  private async typing(ms: number, t: number): Promise<boolean> {
    const it = this.push({ kind: 'typing' });
    await sleep(ms * this.pvSpeed);
    this.chat = this.chat.filter((x) => x !== it);
    this.bump();
    return t === this.P.token;
  }
  private endFlow(): void { this.sys('— end of this flow —'); }
  private async follow(pid: string, t: number): Promise<boolean> {
    const l = this.outLink(pid);
    if (!l) return false;
    await this.go(this.stepOf(l), t, l);
    return true;
  }
  private async go(id: string | undefined, t: number, link?: any): Promise<void> {
    if (t !== this.P.token) return;
    const step = id ? this.steps.get(id) : undefined;
    if (!step) { this.endFlow(); return; }
    this.setRunning(step.id, link);
    if (step.kind === 'trigger') { if (!(await this.follow(step.id + '__then', t))) this.endFlow(); return; }
    if (step.kind === 'actions') {
      for (const a of step.actions!) this.sys(`⚡ ${a.label} · ${a.sub}`, true);
      await sleep(300 * this.pvSpeed);
      await this.follow(step.id + '__next', t);
      return;
    }
    let waitsForTap = false;
    for (const b of step.blocks!) {
      if (t !== this.P.token) return;
      if (b.kind === 'delay') { if (!(await this.typing(Math.min(1400, b.secs! * 350), t))) return; }
      else if (b.kind === 'image') this.bubble('pv-img', '🖼  ' + (b.caption || 'Image'));
      else if (b.kind === 'text') {
        if (!(await this.typing(420, t))) return;
        if (b.text!.trim()) this.bubble('pv-bot', b.text!);
        if (b.buttons!.length) {
          const row = this.push({ kind: 'btns', buttons: b.buttons!.map((btn) => ({ label: (btn.url ? '↗ ' : '') + (btn.title || 'Button'), chosen: false })) });
          this.btnRows.set(row.id, { stepId: step.id, buttons: [...b.buttons!] });
          if (b.buttons!.some((x) => !x.url)) waitsForTap = true;
        }
      } else if (b.kind === 'collect') {
        this.setWaiting({ stepId: step.id, field: b.field!, ar: step.blocks!.some((x) => x.kind === 'text' && isArabic(x.text!)) });
        return;
      }
    }
    // Next Step fires once the message has gone out.
    if (await this.follow(step.id + '__next', t)) return;
    if (!waitsForTap) this.endFlow();
  }
  /** A button in the chat, tapped: it follows that button's own line. */
  async tap(rowId: number, index: number): Promise<void> {
    const row = this.btnRows.get(rowId), btn = row?.buttons[index];
    if (!row || !btn) return;
    this.chat = this.chat.map((x) => x.id !== rowId ? x
      : { ...x, buttons: x.buttons!.map((b, i) => i === index ? { ...b, chosen: true } : b) });
    this.bubble('pv-user', btn.title || 'Button');
    if (btn.url) { this.sys(`Opens ${btn.url.replace(/^https?:\/\//, '')} in the browser`); return; }
    this.setWaiting(null);
    const tok = ++this.P.token;
    if (!(await this.follow(`${row.stepId}__b_${btn.id}`, tok))) this.endFlow();
  }
  setPvText(v: string): void { this.pvText = v; this.bump(); }
  /** The reply box: an invalid answer is asked again; a valid one runs "on reply", then Next Step. */
  async submit(): Promise<void> {
    const w = this.waiting, text = this.pvText.trim();
    if (!w || !text) return;
    this.pvText = '';
    // Clear the box itself too: a framework that batches renders (Qwik) may
    // never have drawn the typed text, so '' would look unchanged to it.
    const box = this.host.querySelector<HTMLInputElement>('#pv-input');
    if (box) box.value = '';
    this.bubble('pv-user', text);
    const t = this.P.token;
    if (!VALID[w.field].test(text)) {
      if (!(await this.typing(380, t))) return;
      this.bubble('pv-bot', w.ar ? 'يبدو أن هذا ليس رقم هاتف صحيحاً، حاول مرة أخرى.' : `That doesn't look like a valid ${w.field.toLowerCase()} — please try again.`);
      return;
    }
    this.setWaiting(null);
    const reply = this.outLink(w.stepId + '__reply');
    if (reply) await this.go(this.stepOf(reply), t, reply);
    if (t !== this.P.token) return;
    if (!(await this.follow(w.stepId + '__next', t))) this.endFlow();
  }
  /** "No reply (24 h)": follow the red line. */
  async noReply(): Promise<void> {
    const w = this.waiting;
    if (!w) return;
    this.setWaiting(null);
    this.sys('⏱ 24 hours pass with no reply');
    if (!(await this.follow(w.stepId + '__noreply', this.P.token))) this.endFlow();
  }
  /** Restart the conversation from the trigger. */
  start(): Promise<void> {
    const t = ++this.P.token;
    this.chat = [];
    this.btnRows.clear();
    this.setWaiting(null);
    this.bubble('pv-user', 'Hi!');
    return this.go('trigger', t);
  }
  setPreview(on: boolean): Promise<void> | void {
    this.previewOn = on;
    this.bump();
    if (on) return this.start();
    this.P.token++; this.setWaiting(null); this.setRunning(null);
  }
  togglePreview(): void { void this.setPreview(!this.previewOn); }

  // The page did these at once; here the framework draws the state first. Run
  // `fn` ONCE, on the first frame the drawn page is `ready` for it (a second
  // run could select a title the user has already started typing over).
  private whenRendered(ready: () => boolean, fn: () => void, frames = 30): void {
    const attempt = () => { if (ready()) fn(); else if (--frames > 0) requestAnimationFrame(attempt); };
    setTimeout(() => requestAnimationFrame(attempt), 0);
  }
  private scrollSoon(): void {
    setTimeout(() => requestAnimationFrame(() => { this.scroll(); requestAnimationFrame(() => this.scroll()); }), 0);
  }
}

